c&=-2.
\end{aligned}
\right.
$$
En appliquant la formule du discriminant
$$
\begin{aligned}
\Delta&=b^2-4ac\\
\Delta&=1^2-4\times1\times-2\\
\Delta&=1+4\times1\times2\\
\Delta&=9>0\\
\sqrt{\Delta}&=3.
  \end{aligned}
$$
$$
\left\{
