\end{aligned}
\right.
$$
Donc on obtient
$$ 
\left\{
\begin{aligned}
x_1&=\dfrac{-4}{2}=-2 \\
x_2&=\dfrac{2}{2}=1.\\
\end{aligned}
\right.
$$
